mapper.update:
UPDATE tb_public_courses
   SET active = FALSE, deactivated_at = #{seenAt}, updated_at = #{seenAt}
 WHERE instt_code = #{insttCode} AND active AND last_seen_at < #{seenAt}

mapper.sql:
WHERE active

    AND (LOWER(lecture_name) LIKE '%' || #{query.keyword} || '%' ESCAPE '\'
         OR LOWER(COALESCE(lecture_content, '')) LIKE '%' || #{query.keyword} || '%' ESCAPE '\'
         OR LOWER(COALESCE(oper_institution_name, '')) LIKE '%' || #{query.keyword} || '%' ESCAPE '\')

AND method = #{query.method}
AND target_types && string_to_array(#{query.targetTypes}, chr(31))
AND region_code = #{query.regionCode}
AND free = #{query.free}
AND COALESCE(edc_end_date, edc_start_date) >= #{query.from}
AND COALESCE(edc_start_date, edc_end_date) <= #{query.to}
AND (edc_end_date IS NULL OR edc_end_date >= #{query.endedFrom})

    AND receipt_end_date >= #{query.receiptOpenOn}
    AND (receipt_start_date IS NULL OR receipt_start_date <= #{query.receiptOpenOn})

AND oper_days && string_to_array(#{query.operDays}, chr(31))
AND start_time >= #{query.startTimeFrom}
AND start_time < #{query.startTimeBefore}
